from typing import List

class TreeNode:
    def __init__(self, value, left=None, right=None):
        self.value = value
        self.left = left
        self.right = right
        self.depth = 0  # Depth of the node in the tree

    def setDepth(self, depth):
        self.depth = depth
        if self.left:
            self.left.setDepth(depth + 1)
        if self.right:
            self.right.setDepth(depth + 1)

    def getLevel(self):
        return self.depth - 1

def buildTree(nodes: List[int]) -> List[int]:
    if not nodes:
        return []

    root = TreeNode(nodes[0])
    queue = [root]
    i = 1
    while i < len(nodes):
        current = queue.pop(0)
        if nodes[i] != -1:
            current.left = TreeNode(nodes[i])
            queue.append(current.left)
        i += 1
        if i < len(nodes) and nodes[i] != -1:
            current.right = TreeNode(nodes[i])
            queue.append(current.right)
        i += 1

    root.setDepth(1)

    levels = []
    for node in queue:
        levels.append(node.getLevel())

    return levels
```

