class IgnoreManager:
    def __init__(self):
        self.ignored_models = []

    def add_model(self, model: str):
        model_lower = model.lower()
        if model_lower not in (existing_model.lower() for existing_model in self.ignored_models):
            self.ignored_models.append(model)

    def remove_model(self, model: str):
        model_lower = model.lower()
        self.ignored_models = [existing_model for existing_model in self.ignored_models if existing_model.lower() != model_lower]

    def is_ignored(self, model: str) -> bool:
        model_lower = model.lower()
        return any(existing_model.lower() == model_lower for existing_model in self.ignored_models)

# Usage example
ignore_manager = IgnoreManager()
ignore_manager.add_model("Model1")
ignore_manager.add_model("Model2")
print(ignore_manager.is_ignored("model1"))  # Output: True
print(ignore_manager.is_ignored("model3"))  # Output: False
ignore_manager.remove_model("Model1")
print(ignore_manager.is_ignored("model1"))  # Output: False
```

