use std::fmt;

// Define the Token struct for representing tokens in the language
struct Token {
    lexeme: String,
    pos: usize,
}

// Define the ParseError enum for representing parsing errors
enum ParseError {
    UnexpectedToken {
        unexpected: Token,
        expected: Option<Token>,
        msg: String,
    },
    MissingToken {
        expected: Token,
    },
}

// Implement the Display trait for ParseError to format error messages
impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            ParseError::UnexpectedToken { unexpected, expected, msg } if msg.is_empty() => {
                write!(
                    f,
                    "Error: Unexpected token \"{}\" at {}",
                    unexpected.lexeme, unexpected.pos
                )
            }
            ParseError::UnexpectedToken { unexpected, expected, msg } => {
                write!(
                    f,
                    "Error \"{}\": {} at {}",
                    unexpected.lexeme, msg, unexpected.pos
                )
            }
            ParseError::MissingToken { expected } => {
                write!(
                    f,
                    "Error: Missing token \"{}\"",
                    expected.lexeme
                )
            }
        }
    }
}

fn main() {
    // Example usage of the ParseError enum
    let unexpected_token = Token {
        lexeme: "}".to_string(),
        pos: 10,
    };
    let expected_token = Token {
        lexeme: "{".to_string(),
        pos: 8,
    };
    let parse_error1 = ParseError::UnexpectedToken {
        unexpected: unexpected_token,
        expected: Some(expected_token),
        msg: "Expected '{'".to_string(),
    };
    let parse_error2 = ParseError::MissingToken {
        expected: Token {
            lexeme: "(".to_string(),
            pos: 15,
        },
    };

    println!("{}", parse_error1); // Output: Error "}": Expected '{' at 10
    println!("{}", parse_error2); // Output: Error: Missing token "("
}
```

