export type WcListFilterHandler<T = any> = (item: T, index: number, list: T[]) => any;

function customFilter<T>(list: T[], filterFn: WcListFilterHandler<T>): T[] {
  const filteredList: T[] = [];
  for (let i = 0; i < list.length; i++) {
    if (filterFn(list[i], i, list)) {
      filteredList.push(list[i]);
    }
  }
  return filteredList;
