import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class LocalVariableOptimizer {
    public List<Integer> optimizeLocalVariableSlots(List<Integer> originalSlots) {
        List<Integer> sortedSlots = new ArrayList<>(originalSlots);
        Collections.sort(sortedSlots);

        List<Integer> optimizedSlots = new ArrayList<>();
        int minSlot = sortedSlots.get(0);
        int maxSlot = sortedSlots.get(sortedSlots.size() - 1);

        for (int i = minSlot; i <= maxSlot; i++) {
            if (sortedSlots.contains(i)) {
                optimizedSlots.add(i);
            }
        }

        return optimizedSlots;
    }
}
```

