```python
import re

def parseCSS(cssCode):
    css_dict = {}
    selector_pattern = r'([^\{\}]+)\s*\{([^\{\}]+)\}'
    property_pattern = r'([^:]+):([^;]+);'

    matches = re.finditer(selector_pattern, cssCode)
    for match in matches:
        selector = match.group(1).strip()
        properties = match.group(2).strip()
        property_matches = re.finditer(property_pattern, properties)
        property_list = [f'{prop.group(1).strip()}: {prop.group(2).strip()}' for prop in property_matches]
        css_dict[selector] = property_list

    return css_dict

# Test the function with the given CSS code snippet
cssCode = """
.formLayout_2 label
{
    text-align: right;
    padding-right: 20px;
    font-size: 16px;
    font-weight: bold;
}

br
{
    clear: left;
}
"""
print(parseCSS(cssCode))
```

The `parseCSS` function uses regular expressions to extract the selectors and their associated properties from the input CSS code. It iterates through the matches to build a dictionary where the keys are the selectors and the values are lists of properties. The function then returns the resulting dictionary.

