use std::collections::HashSet;

fn reallocate(banks: &mut Vec<usize>) {
    let max_blocks = *banks.iter().max().unwrap();
    let max_index = banks.iter().position(|&x| x == max_blocks).unwrap();

    let mut blocks_to_redistribute = banks[max_index];
    banks[max_index] = 0;

    let mut current_index = (max_index + 1) % banks.len();
    while blocks_to_redistribute > 0 {
        banks[current_index] += 1;
        blocks_to_redistribute -= 1;
        current_index = (current_index + 1) % banks.len();
    }
}

fn find_cycle_size(banks: &mut Vec<usize>) -> usize {
    let mut configurations = HashSet::new();
    configurations.insert(banks.clone());

    loop {
        reallocate(banks);
        if configurations.contains(banks) {
            return configurations.len();
        }
        configurations.insert(banks.clone());
    }
}

fn main() {
    let mut banks = vec![0, 2, 7, 0]; // Example input
    let cycle_size = find_cycle_size(&mut banks);
    println!("Size of the cycle: {}", cycle_size);
}
```

