    def keyword(cls) -> str:
        pass

class GreaterThanExp(ComparisonExp):
    def eval(self, variables: Dict[str, int]) -> List[List[str]]:
        return self.rval.eval(variables) + self.lval.eval(variables) + [[OpCodes.COMPARE, "1"]]

    @classmethod
    def keyword(cls) -> str:
        return ">"

class LessThanExp(GreaterThanExp):
    def eval(self, variables: Dict[str, int]) -> List[List[str]]:
        greater_than_eval = super().eval(variables)
        # Reverse the comparison result for less than operation
        for sublist in greater_than_eval:
            if sublist[-1] == "1":
                sublist[-1] = "0"
            elif sublist[-1] == "0":
                sublist[-1] = "1"
        return greater_than_eval

    @classmethod
    def keyword(cls) -> str:
        return "<"
