export default class DistrictRepository extends Repository<District> {
    async getDistricts(getFiltersDistrictsDTO: GetFiltersDistrictsDTO) {
        let { page, limit, search } = getFiltersDistrictsDTO;

        // Set default values if not provided
        if (!page) page = 1;
        if (!limit) limit = 100;

        // Calculate the offset for pagination
        const skip = (page - 1) * limit;

        // Create the query builder
        const query = this.createQueryBuilder('district')
            .orderBy('district', 'ASC')
            .offset(skip)
            .limit(limit);

        // Add search condition if search parameter is provided
        if (search) {
            query.andWhere('district like :search', { search: `%${search}%` });
        }

        // Execute the query and retrieve paginated districts
        const [districts, totalCount] = await query.getManyAndCount();

        return { districts, totalCount };
    }
}
