#[derive(Debug, Serialize, Deserialize)]
pub struct Shape {
    rows: u32,
    columns: u32,
    grid: Vec<Vec<Option<RecipeItem>>>,
}

impl Shape {
    fn new(rows: u32, columns: u32, grid: Vec<Vec<Option<RecipeItem>>>) -> Shape {
        Shape { rows, columns, grid }
    }

    fn display(&self) -> String {
        let mut display_str = String::new();
        for row in &self.grid {
            for cell in row {
                match cell {
                    Some(item) => display_str.push_str(&item.display()),
                    None => display_str.push_str("Empty"),
                }
                display_str.push('\t');
            }
            display_str.push('\n');
        }
        display_str
    }
}

