You are given a binary tree and two integers, `target` and `k`. Your task is to write a function `nodesAtDistanceK` to find and return all the nodes that are at a distance `k` from the node with value `target`. The binary tree is represented using a standard node structure with left and right pointers.

The function signature is:
```c
vector<int> nodesAtDistanceK(TreeNode* root, int target, int k);
```
Where `TreeNode` is defined as:
```c
struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};
```
The function should return a vector of integers containing the values of all nodes that are at a distance `k` from the node with value `target`. If no such nodes exist, an empty vector should be returned.

For example, given the following binary tree:
```
    3
   / \
  5   1
 / \ / \
6  2 0  8
  / \
 7   4
```
If the `target` is `5` and `k` is `2`, the nodes at distance `2` from the node with value `5` are `7`, `4`, and `1`. Therefore, the function should return a vector containing `7`, `4`, and `1`.

```c++
#include <vector>
#include <unordered_map>
#include <queue>

using namespace std;

vector<int> nodesAtDistanceK(TreeNode* root, int target, int k) {
    unordered_map<TreeNode*, TreeNode*> parent; // Map to store parent of each node
    queue<TreeNode*> q; // Queue for BFS traversal
    unordered_map<TreeNode*, bool> visited; // Map to mark visited nodes
    vector<int> result; // Vector to store nodes at distance k

    // Perform BFS to populate the parent map and find the target node
    q.push(root);
    while (!q.empty()) {
        TreeNode* node = q.front();
        q.pop();
        if (node->left) {
            parent[node->left] = node;
            q.push(node->left);
        }
        if (node->right) {
            parent[node->right] = node;
            q.push(node->right);
        }
        if (node->val == target) {
            break;
        }
    }

    // Perform BFS starting from the target node to find nodes at distance k
    q.push(parent[target]);
    visited[parent[target]] = true;
    int level = 0;
    while (!q.empty()) {
        int size = q.size();
        for (int i = 0; i < size; i++) {
            TreeNode* node = q.front();
            q.pop();
            if (level == k) {
                result.push_back(node->val);
            }
            if (node->left && !visited[node->left]) {
                q.push(node->left);
                visited[node->left] = true;
            }
            if (node->right && !visited[node->right]) {
                q.push(node->right);
                visited[node->right] = true;
            }
            if (parent[node] && !visited[parent[node]]) {
                q.push(parent[node]);
                visited[parent[node]] = true;
            }
        }
        level++;
        if (level > k) {
            break;
        }
    }

    return result;
}
```

