 * - Parameter funks: functions to compose.
 *
 * - Returns: A function obtained by composing functions from right to left.
 */
func compose<T>(_ funks: ((T) -> T)...) -> (T) -> T {
    return { input in
        var result = input
        for funk in funks.reversed() {
            result = funk(result)
        }
        return result
    }
}

// Example usage
func addOne(_ x: Int) -> Int {
    return x + 1
}

func multiplyByTwo(_ x: Int) -> Int {
    return x * 2
}

let composed = compose(multiplyByTwo, addOne)
let result = composed(3) // result is 7
```

The `compose` function takes a variable number of single-argument functions and returns a new function that applies each function from right to left. The example usage demonstrates how to use the `compose` function to create a composed function and apply it to an input value.

