// Define an enum for HTTP status codes
#[derive(Debug)]
enum Status {
    Ok,
    MovedPermanently,
    NotFound,
    // Add more status codes as needed
}

// Define the HttpResponse struct
struct HttpResponse {
    status: Option<Status>,
    headers: Vec<(String, String)>,
    body: Option<String>,
}

impl HttpResponse {
    // Create a new instance of HttpResponse
    fn build() -> Self {
        HttpResponse {
            status: None,
            headers: Vec::new(),
            body: None,
        }
    }

    // Set the status of the response
    fn status(mut self, status: Status) -> Self {
        self.status = Some(status);
        self
    }

    // Set the specified header in the response
    fn header(mut self, key: &str, value: &str) -> Self {
        self.headers.push((key.to_string(), value.to_string()));
        self
    }

    // Set the body of the response
    fn body(mut self, body: &str) -> Self {
        self.body = Some(body.to_string());
        self
    }

    // Build the final HTTP response
    fn finalize(self) -> String {
        let mut response = String::new();

        // Append status line
        if let Some(status) = self.status {
            response.push_str(&format!("HTTP/1.1 {}\r\n", status_to_string(status)));
        }

        // Append headers
        for (key, value) in self.headers {
            response.push_str(&format!("{}: {}\r\n", key, value));
        }

        // Append empty line to separate headers and body
        response.push_str("\r\n");

        // Append body
        if let Some(body) = self.body {
            response.push_str(&body);
        }

        response
    }
}

// Helper function to convert Status enum to string representation
fn status_to_string(status: Status) -> &'static str {
    match status {
        Status::Ok => "200 OK",
        Status::MovedPermanently => "301 Moved Permanently",
        Status::NotFound => "404 Not Found",
        // Add more status codes as needed
    }
}

fn main() {
    // Example usage
    let response = HttpResponse::build()
        .status(Status::MovedPermanently)
        .header("Location", "http://example.com")
        .body("The requested resource has moved to: http://example.com")
        .finalize();

    println!("{}", response);
}
```

In the solution, we define the `Status` enum to represent HTTP status codes and the `HttpResponse` struct with associated methods to construct an HTTP response. The `finalize` method is used to build the final HTTP response by combining the status, headers, and body. The `main` function demonstrates an example usage of the `HttpResponse` builder to create an HTTP response with a "Moved Permanently" status, a "Location" header, and a specified body.

