```csharp
public class BitStream
{
    private List<byte> streamBytes;
    private int totalBits;

    public BitStream()
    {
        streamBytes = new List<byte>();
        totalBits = 0;
    }

    public void AddBit(bool val)
    {
        int bytePos = this.totalBits / 8;
        if (bytePos > this.streamBytes.Count - 1 || totalBits == 0)
        {
            this.streamBytes.Add(0);
        }

        if (val)
        {
            int currentByteBit = 7 - (this.totalBits % 8);
            this.streamBytes[bytePos] |= (byte)(1 << currentByteBit);
        }

        this.totalBits++;
    }
}
```

The `AddBit` method updates the `streamBytes` list by adding a new byte if necessary and setting the appropriate bit based on the input value. It also increments the `totalBits` count to keep track of the total number of bits in the stream.

