from typing import Callable, List

class Module:
    def __init__(self, name: str):
        self.name = name

class MultiSequential:
    def __init__(self, modules: List[Module]):
        self.modules = modules

def repeat_modules(N: int, fn: Callable) -> MultiSequential:
    repeated_modules = []
    for _ in range(N):
        module = fn()
        repeated_modules.append(module)
    return MultiSequential(repeated_modules)
