1. `push(val)`: Add an element to the top of the stack.
2. `pop()`: Remove the element from the top of the stack and return its value.
3. `max()`: Return the maximum value in the stack.

Your implementation should have a time complexity of O(1) for each operation.

You are provided with a partially implemented `StackWithMax` class in Swift, which includes a `Stack` class for basic stack operations. Your task is to complete the implementation of the `StackWithMax` class using the provided `Stack` class and ensure that it supports the required operations efficiently.

```swift
import Foundation

class Stack<T> {
    private var elements: [T] = []

    func push(_ val: T) {
        elements.append(val)
    }

    func pop() -> T? {
        return elements.popLast()
    }

    func peek() -> T? {
        return elements.last
    }

    func isEmpty() -> Bool {
        return elements.isEmpty
    }
}

class StackWithMax {
    private var stack: Stack<Int> = Stack<Int>()
    private var maxStack: Stack<Int> = Stack<Int>()

    func push(_ val: Int) {
        stack.push(val)
        if maxStack.isEmpty() || val >= maxStack.peek()! {
            maxStack.push(val)
        }
    }

    func pop() -> Int? {
        if stack.isEmpty() {
            return nil
        }
        let val = stack.pop()
        if val == maxStack.peek() {
            maxStack.pop()
        }
        return val
    }

    func max() -> Int? {
        return maxStack.peek()
    }
}
```

