use std::fmt::Display;

struct FormatTreeNode<T>
where
    T: Display,
{
    payload: T,
    children: Vec<FormatTreeNode<T>>,
}

impl<T> FormatTreeNode<T>
where
    T: Display,
{
    pub fn new(payload: T) -> Self {
        Self {
            payload,
            children: Vec::new(),
        }
    }

    pub fn add_child(&mut self, child: FormatTreeNode<T>) {
        self.children.push(child);
    }

    pub fn display(&self, level: usize) {
        println!("{}{}", "  ".repeat(level), self.payload);
        for child in &self.children {
            child.display(level + 1);
        }
    }
}

fn main() {
    let mut root = FormatTreeNode::new("Root");
    let mut child1 = FormatTreeNode::new("Child1");
    let mut child2 = FormatTreeNode::new("Child2");

    child1.add_child(FormatTreeNode::new("Grandchild1"));
    child1.add_child(FormatTreeNode::new("Grandchild2"));

    root.add_child(child1);
    root.add_child(child2);

    root.display(0);
}
```

