use std::ffi::{CString, OsStr, OsString};
use std::os::unix::ffi::{OsStrExt, OsStringExt};

/// A string in the format OS APIs prefer to consume. For Unix-style
/// platforms, this is similar to `OsString`, but we also need the
/// strings to be NUL-terminated, so we use `CString`.
pub(crate) type HostString = CString;

/// Convert an `OsString` to a `HostString`.
pub(crate) fn hoststring_from_osstring(os: OsString) -> HostString {
    let vec = os.into_vec();
    assert!(!vec.contains(&b'\0')); // Ensure the input does not contain NUL bytes

    let mut vec_with_null = vec;
    vec_with_null.push(0); // Append NUL byte to the vector

    // Create a CString from the vector with NUL byte
    let host_string = unsafe { CString::from_vec_unchecked(vec_with_null) };

    host_string
}
```

In the solution, the `hoststring_from_osstring` function first converts the `OsString` into a vector of bytes using the `into_vec` method. It then ensures that the vector does not contain any NUL bytes using the `assert!` macro. If the assertion passes, it appends a NUL byte to the vector and creates a `CString` from the modified vector using the `from_vec_unchecked` method to ensure NUL termination.

