class CustomUniquePtr {
public:
    explicit CustomUniquePtr(T* ptr) : ptr_(ptr) {}

    T& operator*() const {
        return *ptr_;
    }

    T* operator->() const {
        return ptr_;
    }

    T* release() {
        T* released_ptr = ptr_;
        ptr_ = nullptr;
        return released_ptr;
    }

    ~CustomUniquePtr() {
        delete ptr_;
    }

private:
