// EventEmitter.ts
export class EventEmitter {
  private events: Map<string, Function[]>;

  constructor() {
    this.events = new Map();
  }

  on(eventName: string, listener: Function): void {
    if (!this.events.has(eventName)) {
      this.events.set(eventName, []);
    }
    this.events.get(eventName)!.push(listener);
  }

  emit(eventName: string, ...args: any[]): void {
    const listeners = this.events.get(eventName);
    if (listeners) {
      for (const listener of listeners) {
        listener(...args);
      }
    }
  }

  off(eventName: string, listener: Function): void {
    const listeners = this.events.get(eventName);
    if (listeners) {
      this.events.set(
        eventName,
        listeners.filter((existingListener) => existingListener !== listener)
      );
    }
  }
}
```
The provided solution implements the `EventEmitter` class in TypeScript, fulfilling the requirements outlined in the problem description. The class maintains a map of event names to arrays of listener functions, allowing for event subscription, emission, and removal of specific listeners. The `on` method adds a listener to the specified event, `emit` triggers the event and calls all associated listeners, and `off` removes a specific listener from the event. This implementation ensures that multiple listeners can be added to the same event and that they are called in the order they were added.

