using System;
using System.IO;

public class FileRollback
{
    private BinaryReader reader;
    private MemoryStream mOut;
    private long in_rollback_pos;
    private long out_rollback_len;

    public FileRollback(BinaryReader reader, MemoryStream mOut)
    {
        this.reader = reader;
        this.mOut = mOut;
        in_rollback_pos = reader.BaseStream.Position;
        out_rollback_len = mOut.Length;
