import re

def validate_commit_message(commit_msg: str) -> bool:
    lines = commit_msg.split('\n')  # Split the commit message into individual lines
    commit_msg = ''  # Initialize an empty string to store the extracted commit message
    for line in lines:
        if line.startswith("#"):
            break  # Stop processing if a comment line is encountered
        commit_msg += line + '\n'  # Append the line to the commit message

    commit_msg = commit_msg.rstrip()  # Remove trailing newline characters

    searchObj = re.search("--story=[0-9]+", commit_msg)  # Search for the pattern "--story=[0-9]+" in the commit message
    if searchObj:
        return True  # Return True if the pattern is found
    else:
        return False  # Return False if the pattern is not found
