function processFormData(formData) {
    const errors = {};

    // Validate and extract start date
    const startDate = formData.get('start date');
    if (!startDate) {
        errors.startDate = 'Start date is required';
    } else {
        const startDateRegex = /^\d{4}-\d{2}-\d{2}$/;
        if (!startDate.match(startDateRegex)) {
            errors.startDate = 'Invalid start date format';
        }
    }

    // Validate and extract end date
    const endDate = formData.get('end date');
    if (!endDate) {
        errors.endDate = 'End date is required';
    } else {
        const endDateRegex = /^\d{4}-\d{2}-\d{2}$/;
        if (!endDate.match(endDateRegex)) {
            errors.endDate = 'Invalid end date format';
        }
    }

    // Extract company information
    const company = formData.get('company');

    if (Object.keys(errors).length > 0) {
        return { errors };
    }

    return { startDate, endDate, company };
}
