```php
function processOptions(array $options, array $values): array {
    $result = [];
    $numOptions = count($options);
    $numValues = count($values);

    for ($i = 0; $i < $numOptions; $i++) {
        $option = $options[$i];
        $value = ($i < $numValues) ? $values[$i] : null;
        $result[$option] = $value;
    }

    return $result;
}
