            let metadata = metadata.ok_or_else(|| serde::de::Error::missing_field("metadata"))?;

            Ok(CustomNumber { value, metadata })
        }
    }

    deserializer.deserialize_struct("CustomNumber", &["value", "metadata"], CustomNumberVisitor)
