                for line in file:
                    if not line.startswith('#'):
                        fields = line.strip().split('\t')
                        variant_info = {
                            "CHROM": fields[0],
                            "POS": int(fields[1]),
                            "ID": fields[2],
                            "REF": fields[3],
                            "ALT": fields[4],
                            "QUAL": float(fields[5]),
                            "FILTER": fields[6],
                            "INFO": fields[7]
                        }
                        self.variants.append(variant_info)
        except FileNotFoundError:
            print("File not found.")
        except Exception as e:
            print("An error occurred:", e)

    def get_variants(self):
        return self.variants

    def filter_variants(self, filter_func):
        return list(filter(filter_func, self.variants))

    def write_vcf(self, output_file_path):
        try:
            with open(output_file_path, 'w') as file:
                for variant in self.variants:
                    file.write('\t'.join(str(variant[field]) for field in ["CHROM", "POS", "ID", "REF", "ALT", "QUAL", "FILTER", "INFO"]) + '\n')
        except Exception as e:
            print("An error occurred while writing to the file:", e)
