function fetchAndProcessData($host, $username, $password, $database, $query) {
    // Connect to the MySQL database
    $link = mysqli_connect($host, $username, $password, $database);

    // Check if the connection was successful
    if (!$link) {
        die('Could not connect: ' . mysqli_connect_error());
    }

    // Execute the SQL query to retrieve data
    $result = mysqli_query($link, $query);

    // Process the retrieved data (example: converting to associative array)
    $processedData = array();
    while ($row = mysqli_fetch_assoc($result)) {
        $processedData[] = $row;
    }

    // Free the result set
    mysqli_free_result($result);

    // Close the database connection
    mysqli_close($link);

    // Return a JSON-encoded response containing the processed data
    return json_encode($processedData);
}
