        indegree[target.name] = 0
    }

    for (_, dependencies) in dependencyGraph {
        for dependency in dependencies {
            indegree[dependency, default: 0] += 1
        }
    }

    var queue: [String] = []
    for (target, count) in indegree {
        if count == 0 {
            queue.append(target)
        }
    }

    var result: [String] = []
    while !queue.isEmpty {
        let current = queue.removeFirst()
        result.append(current)
        if let dependencies = dependencyGraph[current] {
            for dependency in dependencies {
                indegree[dependency, default: 0] -= 1
                if indegree[dependency, default: 0] == 0 {
                    queue.append(dependency)
                }
            }
        }
    }

    return result
}

let targets: [Target] = [
    .init(name: "TargetA", dependencies: ["TargetB", "TargetC"]),
    .init(name: "TargetB", dependencies: ["TargetD"]),
    .init(name: "TargetC", dependencies: []),
    .init(name: "TargetD", dependencies: ["TargetE"]),
    .init(name: "TargetE", dependencies: []),
    .init(name: "TargetF", dependencies: ["TargetE"]),
    .init(name: "TargetG", dependencies: ["TargetA", "TargetF"]),
    .init(name: "TargetH", dependencies: ["TargetG"]),
    .init(name: "TargetI", dependencies: ["TargetH"]),
]

let resolvedOrder = resolveDependencies(targets)
print(resolvedOrder)  // Output: ["TargetE", "TargetD", "TargetC", "TargetB", "TargetA", "TargetF", "TargetG", "TargetH", "TargetI"]
