    func fetchItems(completion: @escaping ([Item]?) -> Void) {
        guard let url = URL(string: "https://api.example.com/items") else {
            completion(nil)
            return
        }

        URLSession.shared.dataTask(with: url) { data, response, error in
            guard let data = data, error == nil else {
                completion(nil)
                return
            }

            do {
                let itemsData = try JSONDecoder().decode([Item].self, from: data)
                completion(itemsData)
            } catch {
                completion(nil)
            }
        }.resume()
    }
