```typescript
class OrderMatchingSystem {
    buyOrders: Order[];
    sellOrders: Order[];

    constructor() {
        this.buyOrders = [];
        this.sellOrders = [];
    }

    matchOrders(newBuyOrder: Order): [Order, Order][] {
        const matchedOrders: [Order, Order][] = [];

        for (let i = 0; i < this.sellOrders.length; i++) {
            const sellOrder = this.sellOrders[i];
            if (sellOrder.price <= newBuyOrder.price) {
                matchedOrders.push([newBuyOrder, sellOrder]);
                this.sellOrders.splice(i, 1);
                break;
            }
        }

        return matchedOrders;
    }
}
