```swift
func constructURL(rawPath: String, loadEncoding: String?, password: String?) -> String {
    var modifiedRawPath = rawPath.replacingOccurrences(of: "//", with: "/")

    let urlPath = (try configuration.getApiRootUrl()).appendingPathComponent(modifiedRawPath)
    var urlBuilder = URLComponents(url: urlPath, resolvingAgainstBaseURL: false)!
    var queryItems: [URLQueryItem] = []

    if let encoding = loadEncoding {
        queryItems.append(URLQueryItem(name: "loadEncoding", value: try ObjectSerializer.serializeToString(value: encoding)))
    }

    if let pwd = password {
        let pwdKey = apiInvoker.isEncryptionAllowed() ? "encryptedPassword" : "password"
        queryItems.append(URLQueryItem(name: pwdKey, value: try apiInvoker.encryptString(value: pwd)))
    }

    if !queryItems.isEmpty {
        urlBuilder.queryItems = queryItems
    }

    if let constructedURL = urlBuilder.url {
        return constructedURL.absoluteString
    } else {
        return "Error: Unable to construct URL"
    }
}
```

This solution defines a function `constructURL` that takes the raw path, load encoding, and password as input parameters. It then constructs a URL with the appropriate query parameters based on the given conditions and returns the constructed URL as a string. The function handles the optional load encoding and password values and ensures that the URL is properly constructed with the query parameters.

