public interface GreetingService extends Remote {
    String getGreeting() throws RemoteException;
}

// Remote object implementation
import java.rmi.RemoteException;
import java.rmi.server.UnicastRemoteObject;

public class GreetingServiceImpl extends UnicastRemoteObject implements GreetingService {
    public GreetingServiceImpl() throws RemoteException {
        super();
    }

    @Override
    public String getGreeting() throws RemoteException {
        return "Hello, from the remote server!";
    }
}

// Server
import java.rmi.registry.LocateRegistry;
import java.rmi.registry.Registry;
import java.rmi.Naming;
import java.rmi.server.RMISocketFactory;

public class GreetingServer {
    public static void main(String[] args) {
        try {
            // Set the security policy
            System.setProperty("java.security.policy", "server.policy");

            // Set the codebase for the remote object
            System.setProperty("java.rmi.server.codebase", "http://localhost:8000/");

            // Create and export the remote object
            GreetingService greetingService = new GreetingServiceImpl();
            Registry registry = LocateRegistry.createRegistry(1099);
            registry.rebind("GreetingService", greetingService);

            System.out.println("GreetingService bound and ready for dynamic loading.");
        } catch (Exception e) {
            System.err.println("Server exception: " + e.toString());
            e.printStackTrace();
        }
    }
}

// Client
import java.rmi.Naming;

public class DynamicClient {
    public static void main(String[] args) {
        try {
            // Set the security policy
            System.setProperty("java.security.policy", "client.policy");

            // Set the codebase for the remote object
            System.setProperty("java.rmi.server.codebase", "http://localhost:8000/");

            // Look up the remote object
            GreetingService greetingService = (GreetingService) Naming.lookup("rmi://localhost:1099/GreetingService");

            // Invoke the remote method
            System.out.println(greetingService.getGreeting());
        } catch (Exception e) {
            System.err.println("Client exception: " + e.toString());
            e.printStackTrace();
        }
    }
}
