import React from 'react';
import { Animated } from 'react-native';

interface RunnerHandlerProps {
  shouldStart: boolean;
  getRunner: (animations: Animated.CompositeAnimation[]) => Animated.CompositeAnimation;
}

const RunnerHandler: React.FC<RunnerHandlerProps> = ({ shouldStart, getRunner, children }) => {
  const [isRunning, setIsRunning] = React.useState(false);
  const animationsToRun = React.useRef<Animated.CompositeAnimation[]>([]);

  React.useEffect(() => {
    if (shouldStart && !isRunning) {
      const runner = getRunner(animationsToRun.current);
      runner.start(() => {
        setIsRunning(false);
      });
      setIsRunning(true);
    }
  }, [shouldStart, isRunning, getRunner]);

  const addAnimation = (animation: Animated.CompositeAnimation) => {
    animationsToRun.current.push(animation);
  };

  return <>{React.cloneElement(children, { addAnimation })}</>;
};

interface ParallelProps {
  shouldStart?: boolean;
}

export const Parallel: React.FC<ParallelProps> = ({ children, shouldStart = true }) => {
  const handleAddAnimation = (addAnimation: (animation: Animated.CompositeAnimation) => void) => {
    const animation1 = Animated.timing(new Animated.Value(0), {
      toValue: 100,
      duration: 1000,
      useNativeDriver: true,
    });
    const animation2 = Animated.timing(new Animated.Value(0), {
      toValue: 200,
      duration: 1500,
      useNativeDriver: true,
    });

    addAnimation(Animated.parallel([animation1, animation2]));
  };

  return <RunnerHandler shouldStart={shouldStart} getRunner={animations => Animated.parallel(animations)}>{React.cloneElement(children, { addAnimation: handleAddAnimation })}</RunnerHandler>;
};
```

In this solution, the `RunnerHandler` component manages the execution of animations based on the `shouldStart` prop. It uses the `useEffect` hook to start the animations when `shouldStart` is true and stops them when the animations are completed. The `addAnimation` function is used to add animations to the list of animations to be executed.

The `Parallel` component utilizes the `RunnerHandler` component to handle the parallel execution of animations. It passes the `shouldStart` prop and a function to add animations to the `RunnerHandler`. When the `Parallel` component is rendered, it triggers the `addAnimation` function to add animations to the `RunnerHandler`.

