using System;

public class Vector3
{
    public float x;
    public float y;
    public float z;
    public Vector3 target = new Vector3();

    public float CalculateDistance(Vector3 input)
    {
        float distance = (float)Math.Sqrt(Math.Pow(input.x - target.x, 2) + Math.Pow(input.y - target.y, 2) + Math.Pow(input.z - target.z, 2));
        return distance;
    }
}
