fn to_refs<T>(mut list: Box<&mut List<T>>) -> Vec<&mut T> {
    let mut result = vec![];
    let mut current = &mut list;

    loop {
        result.push(&mut current.value);
        if let Some(next_node) = current.next.as_mut() {
            current = next_node;
        } else {
            break;
        }
    }

    result
}
