use std::collections::HashMap;

struct MetricsTracker {
    counters: HashMap<String, i32>,
    gauges: HashMap<String, i32>,
    histograms: HashMap<String, Vec<i32>>,
}

impl MetricsTracker {
    fn new() -> Self {
        MetricsTracker {
            counters: HashMap::new(),
            gauges: HashMap::new(),
            histograms: HashMap::new(),
        }
    }

    fn increment_counter(&mut self, name: &str, amount: i32) {
        let counter = self.counters.entry(name.to_string()).or_insert(0);
        *counter += amount;
    }

    fn decrement_counter(&mut self, name: &str, amount: i32) {
        let counter = self.counters.entry(name.to_string()).or_insert(0);
        *counter -= amount;
    }

    fn set_gauge(&mut self, name: &str, value: i32) {
        self.gauges.insert(name.to_string(), value);
    }

    fn record_histogram(&mut self, name: &str, value: i32) {
        let histogram = self.histograms.entry(name.to_string()).or_insert(Vec::new());
        histogram.push(value);
    }

    fn get_counter(&self, name: &str) -> Option<&i32> {
        self.counters.get(name)
    }

    fn get_gauge(&self, name: &str) -> Option<&i32> {
        self.gauges.get(name)
    }

    fn get_histogram(&self, name: &str) -> Option<&Vec<i32>> {
        self.histograms.get(name)
    }
}

