using System;
using System.Collections.Generic;
using System.Linq;

public class File
{
    public string FileName { get; set; }
    public string FilePath { get; set; }
}

public enum OpMode
{
    Normal,
    Safe,
    Test
}

public class DriverConfig
{
    public OpMode OpMode { get; set; }
    public List<File> Files { get; set; }
}

public class DriverConfigManager
{
    public void AddFile(DriverConfig driverConfig, File file)
    {
        driverConfig.Files.Add(file);
    }

    public void RemoveFile(DriverConfig driverConfig, string fileName)
    {
        var fileToRemove = driverConfig.Files.FirstOrDefault(f => f.FileName == fileName);
        if (fileToRemove != null)
        {
            driverConfig.Files.Remove(fileToRemove);
        }
    }

    public List<string> ListFiles(DriverConfig driverConfig)
    {
        return driverConfig.Files.Select(f => f.FileName).ToList();
    }
}

