// Define the Event type enum
enum EventType {
    OnPlayerDamage,
    OnPlayerEffect,
    OnPlayerAuth,
    OnPlayerClassChange,
    OnItemPickup,
    OnItemDrop,
    OnCleanRoomActivate
}

// Define the Event class to hold event handlers
class Event {
    private Map<EventType, List<EventHandler>> eventHandlers;

    public Event() {
        eventHandlers = new HashMap<>();
        for (EventType eventType : EventType.values()) {
            eventHandlers.put(eventType, new ArrayList<>());
        }
    }

    public void registerEventHandler(EventType eventType, EventHandler handler) {
        eventHandlers.get(eventType).add(handler);
    }

    public void triggerEvent(EventType eventType) {
        for (EventHandler handler : eventHandlers.get(eventType)) {
            handler.handleEvent();
        }
    }
}

// Define the EventHandler interface
interface EventHandler {
    void handleEvent();
}

// Example implementation of event handlers
class PlayerDamageHandler implements EventHandler {
    @Override
    public void handleEvent() {
        System.out.println("Player damaged!");
    }
}

class ItemPickupHandler implements EventHandler {
    @Override
    public void handleEvent() {
        System.out.println("Item picked up!");
    }
}

// Main program to showcase the event system
public class EventSystemDemo {
    public static void main(String[] args) {
        Event eventSystem = new Event();

        // Register event handlers
        eventSystem.registerEventHandler(EventType.OnPlayerDamage, new PlayerDamageHandler());
        eventSystem.registerEventHandler(EventType.OnItemPickup, new ItemPickupHandler());

        // Trigger events
        eventSystem.triggerEvent(EventType.OnPlayerDamage);
        eventSystem.triggerEvent(EventType.OnItemPickup);
    }
}
