import logging

def check_assumptions(assumptions: List[str], keyword: str) -> Tuple[List[int], List[str]]:
    line_numbers = []
    warning_messages = []

    for i, assumption in enumerate(assumptions, start=1):
        if keyword in assumption:
            line_numbers.append(i)
            if '\\resultfunction' not in assumption:
                warning_messages.append(f"Found assumption containing '{keyword}' but no resultfunction was specified")

    return line_numbers, warning_messages
