class ActionHandler
{
    private $actions;

    /**
     * Constructor to initialize the actions array
     */
    public function __construct($actions)
    {
        $this->actions = $actions;
    }

    /**
     * Retrieves the value for a specific action
     * @param string $action The action to retrieve
     * @return mixed|null The value for the given action, or null if not found
     */
    public function get($action)
