import javax.persistence.EntityManager;
import javax.persistence.Query;
import java.util.ArrayList;
import java.util.List;

public class ContactManager {
    private EntityManager em;
    private List<Contact> contacts;

    public ContactManager(EntityManager em) {
        this.em = em;
        this.contacts = new ArrayList<>();
    }

    // Add a new contact to the list
    public void addContact(Contact contact) {
        em.getTransaction().begin();
        em.persist(contact);
        em.getTransaction().commit();
        contacts.add(contact);
    }

    // Find a contact by id
    public Contact findContactById(int id) {
        for (Contact contact : contacts) {
            if (contact.getId() == id) {
                return contact;
            }
        }
        return null;
    }

    // Remove a contact by id
    public void removeContact(int id) {
        Contact contactToRemove = findContactById(id);
        if (contactToRemove != null) {
            em.getTransaction().begin();
            em.remove(contactToRemove);
            em.getTransaction().commit();
            contacts.remove(contactToRemove);
        }
    }

    // Update a contact by id with new contact information
    public void updateContact(int id, Contact newContact) {
        Contact existingContact = findContactById(id);
        if (existingContact != null) {
            em.getTransaction().begin();
            existingContact.setName(newContact.getName());
            existingContact.setEmail(newContact.getEmail());
            em.merge(existingContact);
            em.getTransaction().commit();
        }
    }
}
