class TaskScheduler {
    var scheduledTasks: [String: Task] = [:]

    func scheduleTask(taskId: String, description: String, executionTime: Date) {
        let task = Task(taskId: taskId, description: description, executionTime: executionTime)
        scheduledTasks[taskId] = task
    }

    func unscheduleTask(taskId: String) {
        scheduledTasks.removeValue(forKey: taskId)
    }

    func getScheduledTasks() -> [String] {
        return Array(scheduledTasks.keys)
    }

    func executeDueTasks(currentTime: Date) -> [String] {
        var executedTasks: [String] = []
        for (taskId, task) in scheduledTasks {
            if task.executionTime <= currentTime {
                executedTasks.append(task.description)
                scheduledTasks.removeValue(forKey: taskId)
            }
        }
        return executedTasks
    }
}

