impl YourStruct {
    pub fn clamping_scale(&self, sample: f32, max_value: i32) -> i32 {
        // Clamp the sample within the range of a 24-bit signed integer
        let clamped_sample = sample.max(-1.0).min(1.0) * (max_value as f32 - 1.0);

        // Round the clamped sample to the nearest integer
        let rounded_sample = clamped_sample.round() as i32;

        // Ensure the rounded sample is within the valid range of a 24-bit signed integer
        if rounded_sample > max_value - 1 {
            max_value - 1
        } else if rounded_sample < -max_value {
            -max_value
        } else {
            rounded_sample
        }
    }

    pub fn f32_to_s24(&mut self, samples: &[f32]) -> Vec<i32> {
        samples
            .iter()
            .map(|sample| self.clamping_scale(*sample, 0x800000) as i32)
            .collect()
    }
}
```

