func calculateTotalArea(rectangles: [(Int, Int, Int, Int)]) -> Int {
    var area = 0
    var points = [Int: Int]()

    for rect in rectangles {
        for x in rect.0..<rect.2 {
            for y in rect.1..<rect.3 {
                let key = x * 1000 + y
                points[key, default: 0] += 1
            }
        }
    }

    for (key, count) in points {
        if count == 1 {
            area += 1
        }
    }

    return area
}
