import java.io.BufferedReader;
import java.io.IOException;

public class DocumentIdentifierExtractor {
    public String extractDocumentIdentifier(BufferedReader in) throws IOException {
        String line;
        String currentDoc = null;

        while ((line = in.readLine()) != null) {
            if (line.contains("DEV-MUC3-")) {
                int start = line.indexOf("DEV-MUC3-");
                currentDoc = line.substring(start, start + 13);
