```java
import java.nio.ByteBuffer;

public class FrameCompletionHandler implements CompletionCheck, CompletionHandler<Long, Void> {

    private final FrameType expected;
    protected final ByteBuffer[] buffers;
    private boolean parsedFrameHeader = false;

    public FrameCompletionHandler(FrameType expected, ByteBuffer[] buffers) {
        this.expected = expected;
        this.buffers = buffers;
    }

    public boolean completeFrame() {
        if (!parsedFrameHeader) {
            // Parse frame header logic
            // If frame header is successfully parsed
            parsedFrameHeader = true;
        }

        // Check if the entire frame has been received
        int totalDataLength = 0;
        for (ByteBuffer buffer : buffers) {
            totalDataLength += buffer.remaining();
        }

        return totalDataLength >= expected.getFrameLength();
    }
}
