public class RelativeOrientationCalculator
{
    public Quaternion CalculateRelativeOrientation(Quaternion MloParentOrientation, Quaternion childOrientation)
    {
        // Calculate the inverse of the parent object's orientation
        Quaternion mloInv = Quaternion.Normalize(Quaternion.Invert(MloParentOrientation));

        // Calculate the relative orientation of the child object with respect to the parent object
        Quaternion relativeOrientation = Quaternion.Normalize(Quaternion.Multiply(mloInv, childOrientation));

        // Calculate the inverse of the relative orientation to get the final result
        Quaternion finalRelativeOrientation = Quaternion.Normalize(Quaternion.Invert(relativeOrientation));

        return finalRelativeOrientation;
    }
}
