```rust
use lazy_static::lazy_static;
use prometheus::{register_int_counter, IntCounter, Encoder, TextEncoder};
use hyper::{Body, Response, Server, Request, Method, StatusCode};
use std::sync::Arc;

lazy_static! {
    static ref CPU_USAGE: IntCounter = register_int_counter!("cpu_usage", "CPU usage in percentage").unwrap();
    static ref MEMORY_USAGE: IntCounter = register_int_counter!("memory_usage", "Memory usage in percentage").unwrap();
    static ref REQUEST_LATENCY: IntCounter = register_int_counter!("request_latency", "Request latency in milliseconds").unwrap();
}

async fn handle_metrics(_: Request<Body>) -> Result<Response<Body>, hyper::Error> {
    let encoder = TextEncoder::new();
    let metric_families = prometheus::gather();
    let mut buffer = vec![];
    encoder.encode(&metric_families, &mut buffer).unwrap();
    Ok(Response::builder()
        .status(StatusCode::OK)
        .header("Content-Type", encoder.format_type())
        .body(Body::from(buffer))
        .unwrap())
}

#[tokio::main]
async fn main() {
    let addr = ([127, 0, 0, 1], 3000).into();
    let make_svc = hyper::service::make_service_fn(|_conn| {
        async { Ok::<_, hyper::Error>(hyper::service::service_fn(handle_metrics)) }
    });
    let server = Server::bind(&addr).serve(make_svc);
    if let Err(e) = server.await {
        eprintln!("server error: {}", e);
    }
}
