public class Animation {
    private Object initialValue;

    public Animation(Object initialValue) {
        this.initialValue = initialValue;
    }

    public void animateTo(Object endValue) {
        if (initialValue instanceof Integer && endValue instanceof Integer) {
            int start = (int) initialValue;
            int end = (int) endValue;
            for (int i = start; i <= end; i++) {
                System.out.println(i);
            }
        } else if (initialValue instanceof String && endValue instanceof String) {
            String start = (String) initialValue;
            String end = (String) endValue;
            int minLength = Math.min(start.length(), end.length());
            for (int i = 0; i <= minLength; i++) {
                System.out.println(start.substring(0, i));
            }
            if (start.length() > end.length()) {
                for (int i = start.length(); i >= end.length(); i--) {
                    System.out.println(start.substring(0, i));
                }
            } else if (end.length() > start.length()) {
                for (int i = start.length(); i <= end.length(); i++) {
                    System.out.println(end.substring(0, i));
                }
            }
        } else {
            System.out.println("Unsupported types for animation");
        }
    }

