import time

timers = {}

def timerStart(timer_name):
    timers[timer_name] = {
        'start_time': time.time(),
        'callbacks': [],
        'running': True
    }

def timerStop(timer_name):
    if timer_name in timers:
        timers[timer_name]['running'] = False

def timerReset(timer_name):
    if timer_name in timers:
        timers[timer_name]['start_time'] = time.time()

def registerCallback(timer_name, interval, callback):
    if timer_name in timers:
        timers[timer_name]['callbacks'].append((interval, callback))

def executeCallbacks(timer_name):
    if timer_name in timers and timers[timer_name]['running']:
        current_time = time.time()
        for interval, callback in timers[timer_name]['callbacks']:
            if current_time - timers[timer_name]['start_time'] >= interval:
                callback()
                timers[timer_name]['start_time'] = current_time

# Usage example
def callbackFunction():
    print("Callback executed")

timerStart("delete")
registerCallback("delete", 1, callbackFunction)  # Register callback to be executed every 1 second
time.sleep(5)  # Wait for 5 seconds
timerStop("delete")  # Stop the timer
```

