```swift
class FontManager {
    func font(forName name: String, size: CGFloat) -> UIFont {
        if name == "system" {
            return UIFont.systemFont(ofSize: size)
        }
        if name.contains("system") {
            let systemName = name.replacingOccurrences(of: "system", with: "").lowercased()
            let weight: UIFont.Weight?
            switch systemName {
                case "black":
                    weight = UIFont.Weight.black
                case "heavy":
                    weight = UIFont.Weight.heavy
                case "light":
                    weight = UIFont.Weight.light
                case "medium":
                    weight = UIFont.Weight.medium
                default:
                    weight = nil
            }
            if let weight = weight {
                return UIFont.systemFont(ofSize: size, weight: weight)
            }
        }
        // If the font name is not "system" or does not contain "system" followed by a weight, return a custom font
        return UIFont(name: name, size: size) ?? UIFont.systemFont(ofSize: size)
    }
}
```

The `FontManager` class provides the `font(forName:size:)` method that handles the logic to generate the appropriate UIFont based on the given font name and size. It first checks if the name is "system" and returns the system font of the specified size. Then, it checks if the name contains "system" followed by a weight, and if so, it parses the weight and returns a system font with the specified weight and size. If the name is not "system" or does not contain "system" followed by a weight, it returns a custom font with the given name and size, or a default system font if the custom font is not found.

