def traverse_array(array: List[List[int]], start_row: int, start_col: int, shape: Tuple[int, int]) -> List[List[int]]:
    res = [[0 for _ in range(shape[1])] for _ in range(shape[0])]
    direction = 'r'
    i, j = start_col, start_row

    for _ in range(shape[0] * shape[1]):
        res[j][i] = array[start_row][start_col]

        if direction == 'r':
            i += 1
            if j == shape[0] - 1:
                direction = 'ur'
            else:
                direction = 'dl'
        elif direction == 'dl':
            i -= 1
            j += 1

        if i < 0 or i == shape[1] or j < 0 or j == shape[0]:
            if direction == 'ur':
                i -= 1
                j += 1
                direction = 'dl'
            elif direction == 'dl':
                i += 1
                j -= 1
                direction = 'ur'

    return res
```

