class Fibonacci:
    def fib_recurs_naive(self, n):
        if n <= 1:
            return n
        else:
            return self.fib_recurs_naive(n-1) + self.fib_recurs_naive(n-2)

    def fib_recurs_fast(self, n):
        memo = {}
        return self._fib_recurs_fast(n, memo)

    def _fib_recurs_fast(self, n, memo):
        if n in memo:
            return memo[n]
        if n <= 1:
            return n
        else:
            memo[n] = self._fib_recurs_fast(n-1, memo) + self._fib_recurs_fast(n-2, memo)
            return memo[n]

def main():
    n = 10  # Replace with the desired value of n
    fib = Fibonacci()
    naive = fib.fib_recurs_naive(n)
    fast = fib.fib_recurs_fast(n)

    if naive != fast:
        print('Wrong answer', naive, fast)
    else:
        print('Ok')

if __name__ == "__main__":
    main()
```

In the solution, the `Fibonacci` class is implemented with two methods: `fib_recurs_naive` and `fib_recurs_fast`. The `fib_recurs_naive` method uses a simple recursive approach to calculate the nth Fibonacci number, while the `fib_recurs_fast` method uses a more efficient recursive approach with memoization to store intermediate results.

