class Heap:
    def __init__(self):
        self.heap = []

    def push(self, item, priority):
        self.heap.append((item, priority))
        self._sift_up(len(self.heap) - 1)

    def pop(self):
        if len(self.heap) == 0:
            raise IndexError("pop from an empty heap")
        self._swap(0, len(self.heap) - 1)
        item, priority = self.heap.pop()
        if self.heap:
            self._sift_down(0)
        return item

    @property
    def top(self):
        if len(self.heap) == 0:
            raise IndexError("top from an empty heap")
        return self.heap[0][0]

    def _sift_up(self, index):
        while index > 0:
            parent = (index - 1) // 2
            if self.heap[parent][1] < self.heap[index][1]:
                self._swap(parent, index)
                index = parent
            else:
                break

    def _sift_down(self, index):
        while index * 2 + 1 < len(self.heap):
            left_child = index * 2 + 1
            right_child = index * 2 + 2 if index * 2 + 2 < len(self.heap) else None
            max_child = left_child
            if right_child and self.heap[right_child][1] > self.heap[left_child][1]:
                max_child = right_child
            if self.heap[index][1] < self.heap[max_child][1]:
                self._swap(index, max_child)
                index = max_child
            else:
                break

    def _swap(self, i, j):
        self.heap[i], self.heap[j] = self.heap[j], self.heap[i]


def test_top_of_heap_always_has_highest_priority():
    heap = Heap()
    for i in range(1, 6):
        heap.push(str(i), -i)
        assert heap.top == "1"
```
In the `Heap` class, the `push` method adds an item to the heap and maintains the heap property by calling `_sift_up` to move the newly added item to its correct position. The `pop` method removes and returns the item with the highest priority, ensuring that the heap property is preserved by calling `_sift_down` after the removal. The `top` method returns the item with the highest priority without removing it from the heap. The test function validates that the top of the heap always has the highest priority after each push operation.

