public class SchedulingAlgorithm
{
    public enum WaitingStrategy
    {
        SpinWait10,
        SpinWait100,
        Sleep1,
        Sleep10
    }

    public WaitingStrategy GetWaitingStrategy(float elapsed, float nextTrigger)
    {
        float diff = nextTrigger - elapsed;
