class GitTagManager:
    def __init__(self):
        self.tags = set()
        self.remote_tags = set()

    def create_tag(self, tag_name):
        self.tags.add(tag_name)
        print(f"Created tag '{tag_name}'")

    def list_tags(self):
        print("Existing tags:")
        for tag in self.tags:
            print(tag)

    def delete_tag(self, tag_name):
        if tag_name in self.tags:
            self.tags.remove(tag_name)
            print(f"Deleted tag '{tag_name}'")
        else:
            print(f"Tag '{tag_name}' does not exist")

    def push_tags(self):
        if self.tags != self.remote_tags:
            self.remote_tags = self.tags.copy()
            print("Pushed tags to remote repository")
        else:
            print("No tag changes to push")

# Example usage
git_manager = GitTagManager()
git_manager.create_tag("v1.0")
git_manager.create_tag("v1.1")
git_manager.list_tags()
git_manager.delete_tag("v1.0")
git_manager.list_tags()
git_manager.push_tags()
```

In this solution, we define a `GitTagManager` class to handle the management of Git tags. The class provides methods to create, list, delete tags, and push changes to a remote repository. The example usage demonstrates how to use the `GitTagManager` to perform these operations.

